Client "1..*" -- "*" Account : opens
Client "1" -- "0..1" Employee : is assigned to personal banker
Division "1" -- "1" Employee : has manager
Division "1" -- "*" Employee : has
CreditCardAccount "1" -- "*" SecondaryCard : has

class Collateral {
  +property : string
}
MortgageAccount "1" -- "1" Collateral : has
@enduml

